ASTR=[['希腊 aster、astron 星；astro-','天上的星，或像星一样向外放射的形状']]
ASTROLOGY=ASTR+[['希腊 astrologia → 拉丁 astrologia → 法语 astrologie／中古英语 astrologie','古时涉及星体的学问；现代 astrology 专指占星术']]
DOX=[['希腊 dokein 看来、认为 → doxa 观点；dogma 认定的主张','人觉得某件事是真的，逐渐形成信念、教义或公认意见']]
DOGMA=DOX+[['希腊 dogma；属格 dogmatos → 拉丁 dogma → 英语 dogma','认定的主张 → 教义、信条']]
DOGMATIC=DOX+[['希腊 dogmatikos → 晚期拉丁 dogmaticus → 法语 dogmatique／英语 dogmatic','与教义相关 → 断言自己的观点绝对正确的']]
ORTHODOX=DOX+[['希腊 orthos 正、直 + doxa 观点 → orthodoxos','被视为正确的信念'],['晚期拉丁 orthodoxus → 法语 orthodoxe／英语 orthodox','合乎正统教义；后来也说符合传统或通行做法']]
HETERODOX=DOX+[['希腊 heteros 不同 + doxa 观点 → heterodoxos → 英语 heterodox','与正统不同的观点 → 非正统的']]
W += [
E('astronaut','/ˈæstrənɔːt/；美亦 /ˈæstrənɑːt/','宇航员；航天员','离开地面，受训去太空执行任务的人。','近代取希腊 astro- 星、外太空 + nautes 船员；字面像在星空中航行的船员，不是古希腊已有的职业名称。',ASTR+[['近代 astro- + -naut → 英语 astronaut','星空 + 航行者 → 太空旅行者、航天员']],'an astronaut on a space station 是空间站上的航天员。名称的星并不要求真的飞到恒星附近，绕地球飞行同样属于太空任务。','train as an astronaut；an astronaut crew；a former astronaut。','astronomer 是研究天体的天文学家；astronaut 是执行航天任务的人。cosmonaut 常见于俄罗斯相关航天语境。',('The astronaut trained for months before joining the mission.','这位航天员在参加任务前训练了数月。'),('The children asked the astronaut how people sleep in space.','孩子们问航天员，人们在太空中怎么睡觉。'),sources=['https://www.etymonline.com/word/astronaut','https://www.oxfordlearnersdictionaries.com/definition/english/astronaut','https://en.wiktionary.org/wiki/astronaut#English']),
E('asterisk','/ˈæstərɪsk/','星号；加星号标注','用一个小星星符号把某处点出来，让读者注意附注、限制或特殊情况。','希腊 asteriskos 是 aster 星的小称，经晚期拉丁 asteriscus 进入英语；先有名词，再有加星号的动词。',ASTR+[['希腊 asteriskos 小星星 → 晚期拉丁 asteriscus → 英语 asterisk','小星状符号 → 星号'],['英语 asterisk〔名词〕→ 同形动词','星号 → 用星号标注']],'an asterisk next to a price 常提示附加条件；asterisk the required fields 是给必填项加星号。在不同软件或标记语法里，它还可能表示通配、乘法或格式。','an asterisk next to；marked with an asterisk；asterisk a word。','star 可泛指星形符号；asterisk 特指文字或代码中的 *。标准词尾是 /rɪsk/，留意 /s/ 在 /k/ 前面。',('An asterisk beside the price points to additional fees below.','价格旁的星号提示读者查看下方的额外费用。'),('Please asterisk the fields that every applicant must complete.','请给每位申请人都必须填写的项目加上星号。'),sources=['https://www.etymonline.com/word/asterisk','https://en.wiktionary.org/wiki/asterisk#English']),
E('aster','英 /ˈæstə/；美 /ˈæstər/','紫菀；紫菀类花卉','花头中心一圈，外围像细小光芒一样展开，所以被借星来命名。','拉丁 aster 接希腊 aster 星；植物名利用花头放射状的外形。',ASTR+[['希腊 aster → 拉丁 aster → 英语植物名 aster','星 → 花头呈星状的紫菀类植物']],'purple asters 是紫色的紫菀花；园艺中 aster 的俗称范围与严格植物分类不必完全重合。这里不把所有菊科花都叫 aster。','purple asters；plant asters；an aster flower。','aster 是一种花的名称；asterisk 是星号。两者共同借了星的外形，却指不同东西。',('Purple asters brightened the autumn garden.','紫色的紫菀花点亮了秋天的花园。'),('She planted asters along the sunny edge of the path.','她在小路向阳的一侧种了紫菀。'),sources=['https://www.etymonline.com/word/aster','https://en.wiktionary.org/wiki/aster#English']),
E('astrologer','英 /əˈstrɒlədʒə/；美 /əˈstrɑːlədʒər/','占星师','根据星体位置和相应象征体系来解读性格、经历或命运的人。','中古英语 astrologie 占星学，或拉丁 astrologus 占星者，加英语人物后缀 -er；与 astronomy 的科学职业名须分清。',ASTROLOGY+[['中古英语 astrologie／拉丁 astrologus + -er → astrologer','研究星体意义的人 → 现代的占星师']],'consult an astrologer 是请占星师解读；an astrologer’s prediction 是占星师的预测。这个职业名不表示其预测已经获得科学验证。','consult an astrologer；an astrologer’s chart；an astrologer’s prediction。','astronomer 是天文学家，主要用观测、数学和物理研究天体；astrologer 是占星师。',('The character visits an astrologer before making a major decision.','故事中的人物在作出重大决定前去见了一位占星师。'),('The newspaper invited an astrologer to explain the horoscope column.','报纸请一位占星师介绍星座运势专栏。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/astrologer','https://en.wiktionary.org/wiki/astrologer#English']),
E('astrological','英 /ˌæstrəˈlɒdʒɪkəl/；美 /ˌæstrəˈlɑːdʒɪkəl/','占星术的；与占星有关的','说某张图、预测或解释来自占星体系。','接拉丁 astrologicus 与英语 -al；现代可与 astrology + -ical 对照记忆，但历史上已有拉丁形容词来源。',ASTR+[['希腊 astrologikos → 拉丁 astrologicus + -al → 英语 astrological','星体学问相关 → 现代特指占星术相关']],'an astrological chart 是占星图；astrological predictions 是占星预测。词尾像 scientific 的学术风格，不等于证据性质也相同。','an astrological chart；astrological signs；astrological predictions。','astronomical 指天文学的，也可比喻数量巨大；astrological 指占星的，不要少看中间几个字母。',('The museum displayed an old astrological chart.','博物馆展出了一张古老的占星图。'),('The article distinguishes astronomical observations from astrological predictions.','文章区分了天文观测与占星预测。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/astrological','https://en.wiktionary.org/wiki/astrological#English']),
E('dogma','英 /ˈdɒɡmə/；美 /ˈdɔːɡmə/，亦 /ˈdɑːɡmə/','教义；信条；被当成定论的主张','一套观点被某个群体当成确定、权威的原则来接受。','希腊 dogma 来自 dokein 认为、觉得，经拉丁 dogma 进入英语；屈折词干 dogmat- 解释了相关词里的 t。',DOGMA,'religious dogma 可中性地说正式教义；challenge the dogma of a field 可批评某领域不容质疑的既定主张。褒贬要看语境。','religious dogma；established dogma；challenge a dogma。','theory 可以接受检验和修正；dogma 强调被认定为权威的信条。不要因为看见 dog 就联想到狗。',('The course examines how religious dogma shaped the debate.','课程考察宗教教义如何影响了这场争论。'),('The researcher challenged a long-standing dogma in the field.','研究者挑战了该领域一条长期被视为定论的主张。'),sources=['https://www.etymonline.com/word/dogma','https://en.wiktionary.org/wiki/dogma#English']),
E('dogmatic','英 /dɒɡˈmætɪk/；美 /dɔːɡˈmætɪk/，亦 /dɑːɡˈmætɪk/','武断的；教条的；教义的','把自己的判断讲得像无须讨论的定论，不愿认真考虑相反证据。','希腊 dogmatikos 接 dogma，经晚期拉丁 dogmaticus、法语 dogmatique 进入英语；不是现代 dogma 直接加 -tic 才出现。',DOGMATIC,'a dogmatic statement 是武断的断言；be dogmatic about something 是对某事执拗地认定只有一种答案。dogmatic theology 则是较中性的教义神学专名。','a dogmatic statement；a dogmatic approach；be dogmatic about。','confident 是有信心；dogmatic 还暗示不肯接受质疑。证据充分、态度坚定并不自动等于教条。',('She is confident in her conclusions without being dogmatic.','她对结论有信心，但并不武断。'),('A dogmatic approach prevented the team from considering alternatives.','教条的做法让团队无法认真考虑其他方案。'),sources=['https://www.etymonline.com/word/dogmatic','https://en.wiktionary.org/wiki/dogmatic#English']),
E('dogmatically','英 /dɒɡˈmætɪkli/；美 /dɔːɡˈmætɪkli/','武断地；教条地','说话时把问题封死，好像自己的答案不用证据支持，也不容别人讨论。','dogmatic + -ally；常用发音中末尾是 /kli/，不必把书写的每个字母读成独立音节。',DOGMATIC+[['英语 dogmatic + -ally → dogmatically','教条的 → 以武断、不容商量的方式']],'state something dogmatically 是武断地下断言；apply a rule dogmatically 是不顾具体情形地死套规则。','assert dogmatically；state dogmatically；apply rules dogmatically。','firmly 只是坚定；dogmatically 加上不肯考虑其他可能的批评。',('He dogmatically insisted that the old method was always best.','他武断地坚持，老方法永远最好。'),('The guideline should not be applied dogmatically to every case.','不应把这条指导原则教条地套用到每一种情况。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/dogmatically','https://en.wiktionary.org/wiki/dogmatically#English']),
E('dogmatism','英 /ˈdɒɡmətɪzəm/；美 /ˈdɔːɡmətɪzəm/，亦 /ˈdɑːɡmətɪzəm/','教条主义；武断态度','把某套主张当成不可动摇的答案，遇到新情况也不肯重新考虑。','法语 dogmatisme 接中世纪拉丁 dogmatismus，最终接 dogma；是已有名词的借入路线，不只是一条现代后缀公式。',DOX+[['拉丁 dogma → 中世纪拉丁 dogmatismus → 法语 dogmatisme → 英语 dogmatism','权威主张 → 固执断言、教条态度']],'intellectual dogmatism 是思想上的教条主义；avoid dogmatism 是保留检验和修正观点的空间。多为批评性用词。','avoid dogmatism；political dogmatism；intellectual dogmatism。','conviction 是坚定信念；dogmatism 的问题通常在于拒绝检验与讨论，而不是有信念本身。',('The seminar encouraged debate rather than dogmatism.','研讨课鼓励讨论，而不是把观点当成不可质疑的定论。'),('Her willingness to revise the model helped the group avoid dogmatism.','她愿意修改模型，帮助团队避免陷入教条主义。'),sources=['https://www.etymonline.com/word/dogmatism','https://www.oxfordlearnersdictionaries.com/definition/english/dogmatism','https://en.wiktionary.org/wiki/dogmatism#English']),
E('dogmatist','英 /ˈdɒɡmətɪst/；美 /ˈdɔːɡmətɪst/，亦 /ˈdɑːɡmətɪst/','教条主义者；武断的人；提出教义的人','把自己的那套答案当成最终标准，常不愿接纳别的解释。','中世纪拉丁 dogmatista 接 dogmatizare 宣说教义和 -ista；英语记录比 dogma 更早，现代可借 dogmat- + -ist 记人名词。',DOX+[['希腊 dogmatizein → 拉丁 dogmatizare → 中世纪拉丁 dogmatista → 英语 dogmatist','宣说教义的人 → 固执于定论的人']],'a political dogmatist 常批评政治观点僵化的人；在历史或哲学讨论中，也可较中性地指建立、阐述教义的人。','a rigid dogmatist；a political dogmatist；no dogmatist。','expert 说明专业知识；dogmatist 说对主张的态度。一个人有专业知识，仍可能愿意修正意见。',('He was a committed reformer, but no dogmatist.','他是一位坚定的改革者，却不是教条主义者。'),('The debate stalled because the loudest dogmatist refused every compromise.','那位嗓门最大的教条主义者拒绝一切妥协，让辩论陷入僵局。'),sources=['https://www.collinsdictionary.com/dictionary/english/dogmatist','https://www.merriam-webster.com/dictionary/dogmatist']),
E('orthodox','英 /ˈɔːθədɒks/；美 /ˈɔːrθədɑːks/','正统的；遵循传统的；东正教或正统派的','符合一个群体通常认可的信念、规则或做法。','希腊 orthos 正、直 + doxa 观点，形成 orthodoxos，经晚期拉丁和法语等路线传入；所谓正确是历史上群体的认定。',ORTHODOX,'an orthodox approach 是常规、正统的方法；Orthodox Christianity、Orthodox Judaism 中的大写词属于宗教名称，具体所指要看传统。不能因词源有正，就断言别的看法客观上都错。','orthodox beliefs；an orthodox approach；Orthodox Christianity；Orthodox Judaism。','traditional 强调沿袭已久；orthodox 强调符合被认可的规范或学说，也可能是在说宗教身份。',('The team began with an orthodox approach before testing new methods.','团队先用常规方法，再测试新办法。'),('The museum displays icons from the Orthodox Christian tradition.','博物馆展出了东正教传统的圣像。'),sources=['https://www.etymonline.com/word/orthodox','https://en.wiktionary.org/wiki/orthodox#English']),
E('orthodoxy','英 /ˈɔːθədɒksi/；美 /ˈɔːrθədɑːksi/','正统观念；通行学说；遵从正统','一套观点在某个领域被普遍接受，成了默认的标准答案。','希腊 orthodoxia 经晚期拉丁 orthodoxia、法语 orthodoxie 进入英语；现代可与 orthodox + -y 对照。',DOX+[['希腊 orthodoxos → orthodoxia → 晚期拉丁 orthodoxia／法语 orthodoxie → 英语 orthodoxy','被认可的正确观点 → 正统学说或遵从正统的状态']],'economic orthodoxy 是经济领域的通行学说；challenge orthodoxy 是挑战既定观念。也有宗教信仰与传统的用法。','challenge orthodoxy；economic orthodoxy；religious orthodoxy；the prevailing orthodoxy。','consensus 强调达成或存在共识；orthodoxy 更突出已建立的规范与学说，不保证所有人一致赞成。',('The discovery challenged the scientific orthodoxy of its time.','这项发现挑战了当时的科学主流观念。'),('The book describes a conflict between innovation and orthodoxy.','这本书描写了创新与正统观念之间的冲突。'),sources=['https://www.etymonline.com/word/orthodoxy','https://en.wiktionary.org/wiki/orthodoxy#English']),
E('unorthodox','英 /ʌnˈɔːθədɒks/；美 /ʌnˈɔːrθədɑːks/','非正统的；不按常规的','没有沿用大家熟悉的标准路线，但可能因此找到另一种办法。','英语 un- 不 + orthodox 正统的；否定的是符合常规，不是自动判定好坏。',ORTHODOX+[['英语 un- + orthodox → unorthodox','不遵循正统或常规的']],'an unorthodox method 是非常规方法；an unorthodox career path 是不走寻常路的职业经历。语气可好可坏，效果另看事实。','an unorthodox approach；unorthodox methods；an unorthodox choice。','unethical 是不道德；unorthodox 只是不按常规，不能因为不常见就判断违背伦理。',('Her unorthodox teaching method kept the class engaged.','她不按常规的教学方法让全班都投入其中。'),('They took an unorthodox route into the industry.','他们通过一条非常规路径进入了这个行业。'),sources=['https://en.wiktionary.org/wiki/unorthodox#English','https://www.oxfordlearnersdictionaries.com/definition/english/unorthodox']),
E('heterodox','英 /ˈhetərədɒks/；美 /ˈhetərədɑːks/','异于正统的；非主流学说的','在一个有公认学说的领域里，持有另一套不同观点。','希腊 heteros 不同 + doxa 观点，形成 heterodoxos 并传入英语。',HETERODOX,'heterodox economics 是不同于主流框架的一类经济学观点；heterodox beliefs 是与正统不同的信念。偏正式，多用于思想、理论与宗教。','heterodox views；heterodox economics；heterodox beliefs。','unorthodox 常说方法、做法不按常规；heterodox 更常说观点、理论与正统不一致，不自动表示错误。',('The journal welcomes heterodox views on economic development.','期刊欢迎关于经济发展的非主流观点。'),('Her heterodox interpretation sparked a lively debate.','她不同于正统的解读引发了热烈讨论。'),sources=['https://www.etymonline.com/word/heterodox','https://www.oxfordlearnersdictionaries.com/definition/english/heterodox','https://en.wiktionary.org/wiki/heterodox#English']),
E('heterodoxy','英 /ˈhetərədɒksi/；美 /ˈhetərədɑːksi/','非正统观点；异端；不遵从正统','把与公认教义或主流理论不同的立场当成一个整体来讨论。','希腊 heterodoxia 接 heterodoxos；英语借入这条名词支线，现代可看作与 heterodox 对应的抽象名词。',DOX+[['希腊 heterodoxos → heterodoxia → 英语 heterodoxy','持有不同意见的 → 非正统立场或观点']],'intellectual heterodoxy 是思想上不循正统；accused of heterodoxy 是被指责观点偏离正统。异端这个译法带历史宗教色彩，不适合所有现代学术语境。','intellectual heterodoxy；religious heterodoxy；a tradition of heterodoxy。','heresy 在宗教中更明确涉及被认定违反教义；heterodoxy 的现代使用范围可以更广，也可中性描述学术立场。',('The university had a tradition of intellectual heterodoxy.','这所大学有不拘正统思想的传统。'),('The historian examines how the community responded to religious heterodoxy.','历史学家研究这个群体如何回应不同于正统的宗教观点。'),sources=['https://www.etymonline.com/word/heterodoxy','https://en.wiktionary.org/wiki/heterodoxy#English','https://www.oxfordlearnersdictionaries.com/definition/english/heterodoxy']),
]
