DEFERRED={'amatory':'较少见文学形容词，优先 amorous。','polyanion':'较专门多电荷阴离子术语，通用词族暂略。','polycation':'较专门多电荷阳离子术语，通用词族暂略。','unionize':'日常义为组织工会，来自 union，与 ion 无关；罕用 un-ionize 化学义暂略。','illusionary':'较少见变体，优先 illusory。','elusory':'较少见形容词，优先 elusive。','illude':'古旧或罕用动词，通用学习暂略。','lusory':'罕用游戏相关形容词，暂略。','astin':'专门天然产物化学名词，暂略。','monaster':'较冷门细胞分裂术语，暂略。','diasterism geaster':'原表连在一起的两个专门词形，通用学习暂略。'}
AM_ROOT=dict(id='C0040',meaning='爱；喜爱；因喜欢而参与',core='先是爱一个人或喜欢一件事，再分出热情参与、含情示爱、为某物倾心。',image='拉丁 amare 爱 → amor 爱、amator 爱好者；法语 amateur → 业余爱好者，enamourer → 使倾心。另列 amoenus 宜人 → amenity，远源联系未定。',intro='amateur 最初是因为喜欢而参与的人，不等于技术差；amateurish 才常批评手法不专业。amorous 说爱情与情欲，enamoured 常说已被吸引。amenity 的直接来源是 amoenus 宜人，与 amare 的更远联系只是一种可能，保留作传统关联。',forms='am-、amat-、amor- 分别对应拉丁动词、分词与名词形式。enamour/enamor、enamoured/enamored 是地区拼写差别。polyamorous 是近代混合构词，不能把它当古希腊或拉丁已有的整词。',branches=[['喜欢而参与','amateur, amateurish, amateurishly, amateurism'],['爱情与倾心','amorous, amorously, enamour, enamor, enamoured, enamored'],['现代关系概念','polyamory, polyamorous'],['远源未定的传统关联','amenity, amenities']],contrasts='amateur 说参与身份，amateurish 常评作品水平。affectionate 可说亲友之情，amorous 偏爱情与情欲。amenities 是便利设施，通常用复数。polyamory 不必涉及婚姻，与 polygamy 不同。',practice='解释为什么一位 amateur photographer 可以很优秀；用 enamoured 说喜欢一座城市；列举酒店的三项 amenities。',words=[w for w in ASSIGN['roots'][115]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][115]['family'] if w in DEFERRED})
ION_ROOT=dict(id='C0590',meaning='去、移动；离子的科学命名',core='用向某处移动的画面命名电解中的带电粒子。今天认离子，要看净电荷，而不是它此刻有没有移动。',image='希腊 ienai 去 → ion 正在去的；katienai 下行、anienai 上行 → 19 世纪 cation、anion、ion 命名体系 → ionic、ionize、ionization。',intro='ion、cation、anion 是近代科学借希腊成分命名的一组词。上、下是历史命名背景，不表示正离子永远向地面移动、负离子永远向天空移动。现代主要分清带正电的 cation 与带负电的 anion。',forms='ion 的读法不等于英语字母 i 加后缀 -on 随意拼。ionic 的重音移到第二音节；ionization 英美中间元音常有差别。普通名词后缀 -ion，如 action 末尾，并不是这组离子词。',branches=[['带电粒子','ion, cation, anion'],['性质与成键','ionic, cationic, anionic'],['形成离子的过程','ionize, ionization']],contrasts='electron 是电子，ion 是带净电荷的原子或分子粒子。ionic 与大写 Ionic 爱奥尼亚的不同源。unionize 组织工会来自 union，不能从拼写中切出 ionize 来解释。',practice='比较 cation 与 anion 的电荷；解释离子为什么不一定正在移动；用 ionic compound 与 ionization 分别说物质和过程。',words=[w for w in ASSIGN['roots'][116]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][116]['family'] if w in DEFERRED})
LUD_ROOT=dict(id='C0689',meaning='玩；演奏；戏弄；躲闪',core='玩可以是演奏，也可以是戏弄对方、绕着对方走；从这些具体动作发展出序幕、错觉、暗指和逃脱。',image='拉丁 ludere 玩、戏弄 → prae-ludere 先演奏、interludium 中间的戏；illudere 欺骗、eludere 躲开、alludere 影射、colludere 串通。',intro='这组最有用的不是逐字翻译玩，而是记住几个不同场景。prelude、interlude 是时间位置；illusion、delusion 是表象与信念；elusive 是抓不住；allusion 是只给线索；collusion 是暗中配合。',forms='lud- 与 lus- 来自拉丁动词和分词词干变化。allusive、elusive、collusive 中通常读 /s/，illusion、allusion、collusion 中是 /ʒ/。很多 -ion 名词有独立借入路线，collusion 在英语中还早于 collude。',branches=[['前面与中间的表演','prelude, interlude'],['错觉与错误信念','illusion, illusory, illusionist, delude, deluded, delusion, delusional'],['幻想破灭','disillusion, disillusioned, disillusionment'],['抓不住','elude, elusive, elusively, elusiveness'],['间接提到','allude, allusion, allusive'],['暗中串通','collude, collusion, collusive'],['荒唐得像玩笑','ludicrous, ludicrously']],contrasts='elusive 是难以把握；illusory 是表象不实；allusive 是含暗指。disappointment 可以只是一次失望，disillusionment 更常涉及理想或信任的破灭。cooperate 是合作，collude 通常是负面的串通。',practice='分别用 illusion、delusion、elusive 描写三个场景；解释 collusion 为什么不宜称赞团队合作；比较 prelude 与 interlude 出现的位置。',words=[w for w in ASSIGN['roots'][117]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][117]['family'])+ASSIGN['roots'][117]['unmatched'] if w in DEFERRED})
ASTR_ROOT=dict(id='C0090',meaning='星；星状；天体与太空',core='抬头看到星空，再把星的形状、天体的研究和对命运的旧联想带进词语。',image='希腊 aster、astron 星 → asterisk 小星号、aster 星状花；astro- + -naut → 航天员。意大利 disastro 不吉星位 → 法语 désastre → disaster。',intro='astronomy 与 astrology 曾有历史交叠，现代必须分开：前者是天文学，后者是占星术。asteroid 因看上去像星点而得名，却不是恒星。disaster 保留了把厄运归于星位的旧观念，今天已是普通灾难词。',forms='aster- 与 astr-、astro- 是相关形式；astronaut 并不拆成英语 star。asterisk 的 -isk 接希腊小称后缀，意为小星。astronomical 还能表示大得惊人，astrological 则与占星有关。',branches=[['观测与研究','astronomy, astronomer, astronomical, astronomically, astrophysics, astrophysicist'],['太空与天体','astronaut, asteroid, astral'],['小星状外形','asterisk, aster'],['占星与解释命运','astrology, astrologer, astrological'],['不利星位的旧比喻','disaster, disastrous, disastrously']],contrasts='astronomer 研究天体，astronaut 执行航天任务，astrologer 解读占星体系。aster 是花，asterisk 是星号。disastrous 有法语或意大利形容词借入支线，不应只画成英语 disaster 加 -ous。',practice='解释为什么 astronaut 不必飞到恒星旁边；在 asterisk 提示下找附注；用 disaster 分别说真实灾害和一次糟糕的尝试。',words=list(dict.fromkeys([w for w in ASSIGN['roots'][118]['family'] if w not in DEFERRED]+['astronomical','astronomically','astrophysics'])),exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][118]['family'])+ASSIGN['roots'][118]['unmatched'] if w in DEFERRED})
DOG_ROOT=dict(id='C0335',meaning='认为；观点；信条；公认与不同意见',core='先是觉得某件事是真的，再形成自己的看法，甚至成为整个群体认定的标准。',image='希腊 dokein 认为 → doxa 观点、dogma 信条；orthos 正 + doxa → orthodox，heteros 不同 + doxa → heterodox，para- 旁、相违 + doxa → paradox。',intro='orthodox 是符合公认规范，heterodox 是观点不同；unorthodox 更常说做法不循常规。dogmatic 则批评把自己的观点当成不容质疑的定论。词源里的正确只是历史上的群体认定，不是对所有思想作真假裁决。',forms='dogma 的希腊屈折词干是 dogmat-，所以 dogmatic、dogmatism 中有 t。dogmatist 还有更早的中世纪拉丁借入路线。dog- 在这里与英语 dog 狗不同源。doxa 也有荣耀、赞美义，进入 doxology。',branches=[['信条与武断态度','dogma, dogmatic, dogmatically, dogmatism, dogmatist'],['正统与常规','orthodox, orthodoxy, unorthodox'],['不同的理论或信念','heterodox, heterodoxy'],['违背常识的表面矛盾','paradox, paradoxical, paradoxically'],['赞美与宗教用语','doxology']],contrasts='confident 有信心不等于 dogmatic 武断；unorthodox 不按常规不等于 unethical 不道德。paradox 的表面矛盾可能揭示真实道理，也可能需要逻辑分析。大写 Orthodox 在宗教名称里要按具体传统理解。',practice='比较 orthodox 与 unorthodox methods；解释 dogmatic 为什么不能只译为自信；用 allusion 和 paradox 各描述一种表达技巧。',words=list(dict.fromkeys([w for w in ASSIGN['roots'][119]['family'] if w not in DEFERRED]+['paradoxically'])),exclude={})
roots=[AM_ROOT,ION_ROOT,LUD_ROOT,ASTR_ROOT,DOG_ROOT]
ALREADY={'delude','asteroid'}
expected={w for r in ASSIGN['roots'][115:120] for w in r['family'] if w in set(ASSIGN['owned_words']) and w not in DEFERRED and w not in ALREADY}
assert {w['word'] for w in W}==expected,({w['word'] for w in W}-expected,expected-{w['word'] for w in W})
assert len(W)==len({w['word'] for w in W})
assert all(len(w['examples'])>=2 and all(len(e)==2 and all(e) for e in w['examples']) for w in W)
assert all(all(w.get(k) for k in ['ipa','meaning','sense','split','history','explanation','usage','contrast','sources']) for w in W)
assert all(len(w['history'])>=2 and all(len(h)==2 and all(h) for h in w['history']) for w in W)
for kind,data in [('roots',roots),('words',W)]: (OUT/f'{kind}_batch200_st_33.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
Path('.cache/batch200/st33-working-words.json').unlink(missing_ok=True)
p=Path('.cache/batch200/rewrite_st_progress.json');progress=json.loads(p.read_text())
progress['completed_roots']=list(dict.fromkeys(progress['completed_roots']+[r['id'] for r in roots]))
