progress['batches']=list(dict.fromkeys(progress['batches']+['batch200_st_33']))
progress.setdefault('deferred_words',{}).update(DEFERRED)
progress.update(next_root_index=120,next_root_id=ASSIGN['roots'][120]['id'],status='writing',active_script=None,active_written_words=0,active_note='st33 am14/ion4/lud22/astr10/dog10=60new;5roots;11exclude. Next Pan/stin/pred/dram/trunc indices120–124.')
p.write_text(json.dumps(progress,ensure_ascii=False,indent=2)+'\n')
print('st33',len(roots),'roots',len(W),'newwords',sum(len(w['examples']) for w in W),'examples',len(DEFERRED),'deferred')
